def verify(perm):
    n = len(perm)
    vectors = {}
    for c1 in range(n):
        for c2 in range(c1+1, n):
            dr = perm[c2] - perm[c1]
            dc = c2 - c1
            key = (dr, dc)
            if key in vectors:
                print(f"  Conflict: ({c1},{perm[c1]}) and ({c2},{perm[c2]}) -> {key}")
                return False
            vectors[key] = ((c1, perm[c1]), (c2, perm[c2]))
    print(f"  All {n*(n-1)//2} vectors distinct: {sorted(vectors.keys())}")
    return True

for sol in [[0, 2, 3, 1, 4], [0, 4, 3, 1, 2], [1, 0, 3, 4, 2], [1, 4, 3, 0, 2],
            [2, 0, 3, 4, 1], [2, 1, 3, 4, 0], [2, 4, 3, 0, 1], [4, 1, 3, 2, 0]]:
    print(f"Solution {sol}:")
    verify(sol)
